  2771  sc_pkcs15init_select_intrinsic_id(struct sc_pkcs15_card *p15card, struct sc_profile *profile,
  2772                  int type, struct sc_pkcs15_id *id_out, void *data)
  2773  {
  2774  #ifndef ENABLE_OPENSSL
  2775          LOG_FUNC_RETURN(p15card->card->ctx, SC_SUCCESS);
  2776  #else
  2777          struct sc_context *ctx = p15card->card->ctx;
  2778          struct sc_pkcs15_pubkey *pubkey = NULL;
  2779          unsigned id_style;
  2780          struct sc_pkcs15_id id;
  2781          unsigned char *id_data = NULL;
  2782          size_t id_data_len = 0;
  2783          int rv, allocated = 0;
  2784
  2785          LOG_FUNC_CALLED(ctx);
  2786
  2787          if (!id_out || !profile)
  2788                  LOG_FUNC_RETURN(ctx, SC_ERROR_INVALID_ARGUMENTS);
  2789
  2790          id_style = profile->id_style;
  2791
  2792          /* ID already exists */
  2793          if (id_out->len)
  2794                  LOG_FUNC_RETURN(ctx, SC_SUCCESS);
  2795
  2796          /* Native ID style is not intrinsic one */
  2797          if (id_style == SC_PKCS15INIT_ID_STYLE_NATIVE)
  2798                  LOG_FUNC_RETURN(ctx, SC_SUCCESS);
  2799
  2800          memset(&id, 0, sizeof(id));
  2801          /* Get PKCS15 public key */
  2802          switch(type)   {
  2803          case SC_PKCS15_TYPE_CERT_X509:
  2804                  rv = sc_pkcs15_pubkey_from_cert(ctx, (struct sc_pkcs15_der *)data, &pubkey);
  2805                  LOG_TEST_RET(ctx, rv, "X509 parse error");
  2806                  allocated = 1;
  2807                  break;
  2808          case SC_PKCS15_TYPE_PRKEY:
  2809                  rv = sc_pkcs15_pubkey_from_prvkey(ctx, (struct sc_pkcs15_prkey *)data, &pubkey);
  2810                  LOG_TEST_RET(ctx, rv, "Cannot get public key");
  2811                  allocated = 1;
  2812                  break;
  2813          case SC_PKCS15_TYPE_PUBKEY:
  2814                  pubkey = (struct sc_pkcs15_pubkey *)data;
  2815                  allocated = 0;
  2816                  break;
  2817          default:
  2818                  sc_log(ctx, "Intrinsic ID is not implemented for the object type 0x%X", type);
  2819                  LOG_FUNC_RETURN(ctx, SC_SUCCESS);
  2820          }
  2821
  2822          /* Skip silently if key is not initialized. */
  2823          if (pubkey->algorithm == SC_ALGORITHM_RSA && !pubkey->u.rsa.modulus.len)
  2824                  goto done;
  2825          else if (pubkey->algorithm == SC_ALGORITHM_GOSTR3410 &&
  2826                          !pubkey->u.gostr3410.xy.data)
  2827                  goto done;
  2828          else if (pubkey->algorithm == SC_ALGORITHM_EC && !pubkey->u.ec.ecpointQ.value)
  2829                  goto done;
  2830
  2831          /* In Mozilla 'GOST R 34.10' is not yet supported.
  2832           * So, switch to the ID recommended by RFC2459 */
  2833          if (pubkey->algorithm == SC_ALGORITHM_GOSTR3410 && id_style == SC_PKCS15INIT_ID_STYLE_MOZILLA)
  2834                  id_style = SC_PKCS15INIT_ID_STYLE_RFC2459;
