   643          /* if we didn't get a label, set one based on the CN */
   644          if (*cert->cert_p15obj->label == '\0') { /* can't be NULL -- static array */
   645                  static const struct sc_object_id cn_oid = {{ 2, 5, 4, 3, -1 }};
   646                  u8 *cn_name = NULL;
   647                  size_t cn_len = 0;
