   653                                          (unsigned int) cn_len, cn_name);
   654                          cn_len = MIN(cn_len, SC_PKCS15_MAX_LABEL_SIZE-1);
   655                          memcpy(cert->cert_p15obj->label, cn_name, cn_len);
   656                          cert->cert_p15obj->label[cn_len] = '\0';
