   662  static int
   663  __pkcs15_create_cert_object(struct pkcs15_fw_data *fw_data, struct sc_pkcs15_object *cert,
   664                  struct pkcs15_any_object **cert_object)
   665  {
   666          struct sc_pkcs15_cert_info *p15_info = NULL;
   667          struct sc_pkcs15_cert *p15_cert = NULL;
   668          struct pkcs15_any_object *any_object = NULL;
   669          struct pkcs15_cert_object *object = NULL;
   670          struct pkcs15_pubkey_object *obj2 = NULL;
   671          struct pkcs15_any_object *any_object2 = NULL;
   672          int rv;
   673
   674          p15_info = (struct sc_pkcs15_cert_info *) cert->data;
   675
   676          if (cert->flags & SC_PKCS15_CO_FLAG_PRIVATE)  { /* is the cert private? */
   677                  p15_cert = NULL;                        /* will read cert when needed */
   678          }
   679          else    {
   680                  rv = sc_pkcs15_read_certificate(fw_data->p15_card, p15_info, 0, &p15_cert);
   681                  if (rv < 0)
   682                          return rv;
   683          }
   684
   685          /* Certificate object */
   686          rv = __pkcs15_create_object(fw_data, &any_object,
   687                          cert, &pkcs15_cert_ops, sizeof(struct pkcs15_cert_object));
   688          object = (struct pkcs15_cert_object *) any_object;
   689          if (rv < 0) {
   690                  if (p15_cert != NULL)
   691                          sc_pkcs15_free_certificate(p15_cert);
   692                  return rv;
   693          }
   694
   695          object->cert_info = p15_info;
   696          object->cert_data = p15_cert;
   697
   698          /* Corresponding public key */
   699          rv = public_key_created(fw_data, &p15_info->id, &any_object2);
   700          if (rv != SC_SUCCESS)
   701                  rv = __pkcs15_create_object(fw_data, &any_object2,
   702                                  NULL, &pkcs15_pubkey_ops, sizeof(struct pkcs15_pubkey_object));
   703          obj2 = (struct pkcs15_pubkey_object *) any_object2;
   704          if (rv < 0)
   705                  return rv;
   706
   707          if (p15_cert) {
   708                   /* make a copy of public key from the cert */
   709                  if (!obj2->pub_data)
   710                          rv = sc_pkcs15_pubkey_from_cert(context, &p15_cert->data, &obj2->pub_data);
   711                  if (rv < 0)
   712                          return rv;
   713          }
   714
   715          obj2->pub_genfrom = object;
   716          object->cert_pubkey = obj2;
   717
   718          /* Find missing labels for certificate */
   719          pkcs15_cert_extract_label(object);
