  1008  /* We deferred reading of the cert until needed, as it may be
  1009   * a private object, so we must wait till login to read  */
  1010  static int
  1011  check_cert_data_read(struct pkcs15_fw_data *fw_data, struct pkcs15_cert_object *cert)
  1012  {
  1013          struct pkcs15_pubkey_object *obj2;
  1014          int rv;
  1015          int private_obj;
  1016
  1017          if (!cert)
  1018                  return SC_ERROR_OBJECT_NOT_FOUND;
  1019
  1020          if (cert->cert_data)
  1021                  return 0;
  1022          private_obj = cert->cert_flags & SC_PKCS15_CO_FLAG_PRIVATE;
  1023          rv = sc_pkcs15_read_certificate(fw_data->p15_card, cert->cert_info, private_obj, &cert->cert_data);
  1024          if (rv < 0)
  1025                  return rv;
  1026
  1027          obj2 = cert->cert_pubkey;
  1028          /* make a copy of public key from the cert data */
  1029          if (!obj2->pub_data)
  1030                  rv = sc_pkcs15_pubkey_from_cert(context, &cert->cert_data->data, &obj2->pub_data);
  1031
  1032          /* Find missing labels for certificate */
  1033          pkcs15_cert_extract_label(cert);
  1034
  1035          /* now that we have the cert and pub key, lets see if we can bind anything else */
  1036          pkcs15_bind_related_objects(fw_data);
  1037
  1038          return rv;
  1039  }
